// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, uint256 v, address to1, address to2, bool useTwo) public {
        address[] memory tos = new address[](useTwo ? 2 : 1);
        tos[0] = to1;
        if (useTwo) tos[1] = to2;
        // low-level call to a plain (EOA) caddress succeeds, so transfer completes normally
        assertTrue(c.transfer(from, caddress, tos, v), "transfer must return true on success");
    }
}
